<template><section v-if="v"><div class="playerWrap"><Player :src="src"/></div><div class="playInfo"><h1>{{v.vod_name}}</h1><p>{{v.vod_blurb||''}}</p></div></section><div v-else class="empty">加载中...</div></template><script setup>import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {getDetail,detailItem,playUrl} from '../api/vod';import Player from '../components/Player.vue';const r=useRoute(),v=ref(null),src=ref('');onMounted(async()=>{try{v.value=detailItem(await getDetail(r.params.id));src.value=playUrl(v.value);const h=JSON.parse(localStorage.getItem('history')||'[]').filter(x=>x.id!==v.value.vod_id);h.unshift({id:v.value.vod_id,name:v.value.vod_name,pic:v.value.vod_pic});localStorage.setItem('history',JSON.stringify(h.slice(0,30)))}catch{}})</script>
